/** Atributo opcional para registrar la longitud del calado, definida en pies, con la que cuenta la embarcación o el buque en el que se transportan los bienes y/o mercancías.
 * @maxInclusive 0.01
 **/
export interface Calado extends XastElement {
	name: string;
	children: [
		{
			type: 'text';
			/**
			 * @maxInclusive 0.01
			 **/
			value: string;
		},
	];
}
/** Atributo opcional para registrar la longitud del calado, definida en pies, con la que cuenta la embarcación o el buque en el que se transportan los bienes y/o mercancías.
 * @maxInclusive 0.01
 **/
export type CartaPorteMercanciasTransporteMaritimoCalado = string;

/** Tipo definido para expresar la calle en que está ubicado el domicilio del emisor del comprobante o del destinatario de la mercancía.
 * @pattern [^|]{1,100}
 * @minLength 1
 * @maxLength 100
 **/
export interface Calle extends XastElement {
	name: string;
	children: [
		{
			type: 'text';
			/**
			 * @pattern [^|]{1,100}
			 * @minLength 1
			 * @maxLength 100
			 **/
			value: string;
		},
	];
}
/** Tipo definido para expresar la calle en que está ubicado el domicilio del emisor del comprobante o del destinatario de la mercancía.
 * @pattern [^|]{1,100}
 * @minLength 1
 * @maxLength 100
 **/
export type TDescrip100 = string;

/** Atributo requerido para expresar la cantidad total de los bienes y/o mercancías que se trasladan a través de los distintos medios de transporte.
 * @maxInclusive 0.000001
 **/
export interface Cantidad extends XastElement {
	name: string;
	children: [
		{
			type: 'text';
			/**
			 * @maxInclusive 0.000001
			 **/
			value: string;
		},
	];
}
/** Atributo requerido para expresar la cantidad total de los bienes y/o mercancías que se trasladan a través de los distintos medios de transporte.
 * @maxInclusive 0.000001
 **/
export type CartaPorteMercanciasMercanciaCantidad = string;

/** Atributo requerido para expresar el número de bienes y/o mercancías que se trasladan en los distintos medios de transporte.
 * @maxInclusive 0.000001
 **/
export type CartaPorteMercanciasMercanciaCantidadTransportaCantidad = string;

/** Nodo opcional para registrar la cantidad de los bienes y/o mercancías que se trasladan a través de los distintos medios de transporte, que será captada o distribuida en distintos puntos, a fin de identificar el punto de origen y destino correspondiente.**/
export interface CartaPorteMercanciasMercanciaCantidadTransporta extends XastElement {
	type: 'element';
	name: 'CantidadTransporta';
	attributes: {
		/** Atributo requerido para expresar el número de bienes y/o mercancías que se trasladan en los distintos medios de transporte.	**/
		Cantidad: string;
		/** Atributo condicional para indicar la clave a través de la cual se identifica el medio por el que se transportan los bienes y/o mercancías.	**/
		CvesTransporte?: catCartaPorte.CCveTransporte;
		/** Atributo requerido para registrar la clave del identificador del destino de los bienes y/o mercancías que se trasladan a través de los distintos medios de transporte, de acuerdo al valor registrado en el atributo “IDUbicacion”, del nodo “Ubicacion”.	**/
		IDDestino: string;
		/** Atributo requerido para expresar la clave del identificador del origen de los bienes y/o mercancías que se trasladan por los distintos medios de transporte, de acuerdo al valor registrado en el atributo “IDUbicacion”, del nodo “Ubicacion”.	**/
		IDOrigen: string;
	};
	/** XastElement is self-closing */
	children: [];
}

/** Tipo definido para expresar importes numéricos con fracción hasta seis decimales. No se permiten valores negativos.
 * @pattern [0-9]{1,18}(.[0-9]{1,6})?
 * @maxInclusive 0.000000
 **/
export interface CargoPorTasacion extends XastElement {
	name: string;
	children: [
		{
			type: 'text';
			/**
			 * @pattern [0-9]{1,18}(.[0-9]{1,6})?
			 * @maxInclusive 0.000000
			 **/
			value: string;
		},
	];
}
/** Tipo definido para expresar importes numéricos con fracción hasta seis decimales. No se permiten valores negativos.
 * @pattern [0-9]{1,18}(.[0-9]{1,6})?
 * @maxInclusive 0.000000
 **/
export type TImporte = string;

/** Nodo requerido para registrar la información que permite identificar el (los) carro(s) en el (los) que se trasladan los bienes y/o mercancías por vía férrea.**/
export interface CartaPorteMercanciasTransporteFerroviarioCarro extends XastElement {
	type: 'element';
	name: 'Carro';
	attributes: {
		/** Atributo requerido para registrar el número de guía asignado al contenedor, carro de ferrocarril o vehículo, en el que se trasladan los bienes y/o mercancías por vía férrea.	**/
		GuiaCarro: string;
		/** Atributo requerido para registrar el número de contenedor, carro de ferrocarril o número económico del vehículo en el que se trasladan los bienes y/o mercancías por vía férrea.	**/
		MatriculaCarro: string;
		/** Atributo requerido para registrar la clave del tipo de carro utilizado para el traslado de los bienes y/o mercancías por vía férrea.	**/
		TipoCarro: catCartaPorte.CTipoCarro;
		/** Atributo requerido para registrar la cantidad de las toneladas netas depositadas en el contenedor, carro de ferrocarril o vehículo en el que se trasladan los bienes y/o mercancías por vía férrea.	**/
		ToneladasNetasCarro: string;
	};
	children: CartaPorteMercanciasTransporteFerroviarioCarroContenedor[];
}

/** Complemento para incorporar al Comprobante Fiscal Digital por Internet (CFDI), la información relacionada a los bienes y/o mercancías, ubicaciones de origen, puntos intermedios y destinos, así como lo referente al medio por el que se transportan; que circulen por vía terrestre, férrea, aérea o naveguen por vía marítima; además de incluir el traslado de hidrocarburos y petrolíferos.**/
export interface CartaPorte extends XastElement {
	type: 'element';
	name: 'CartaPorte';
	attributes: {
		/** Atributo condicional para precisar si los bienes y/o mercancías ingresan o salen del territorio nacional.	**/
		EntradaSalidaMerc?: CartaPorteEntradaSalidaMerc;
		/** Atributo requerido para expresar los 36 caracteres del folio del complemento Carta Porte (IdCCP) de la transacción de timbrado conforme al estándar RFC 4122, para la identificación del CFDI con complemento Carta Porte.	**/
		IdCCP: string;
		/** Atributo condicional para registrar la clave del país de origen o destino de los bienes y/o mercancías que se trasladan a través de los distintos medios de transporte.	**/
		PaisOrigenDestino?: catCFDI.CPais;
		/** Atributo condicional para expresar el tipo de régimen que se encuentra asociado con el traslado de los bienes y/o mercancías de procedencia extranjera.	**/
		RegimenAduanero?: catCartaPorte.CRegimenAduanero;
		/** Atributo opcional para registrar las regiones, sí el traslado de los bienes y/o mercancías se realiza al interior de los Polos de Desarrollo para el Bienestar del istmo de Tehuantepec.	**/
		RegistroISTMO?: CartaPorteRegistroISTMO;
		/** Atributo condicional para indicar en kilómetros, la suma de las distancias recorridas, registradas en el atributo “DistanciaRecorrida”, para el traslado de los bienes y/o mercancías.	**/
		TotalDistRec?: string;
		/** Atributo requerido para expresar si los bienes y/o mercancías que son transportadas ingresan o salen del territorio nacional.	**/
		TranspInternac: CartaPorteTranspInternac;
		/** Atributo condicional para registrar la región en donde termina el traslado de los bienes y/o mercancias al interior de los Polos de Desarrollo para el Bienestar del istmo de Tehuantepec.	**/
		UbicacionPoloDestino?: catCartaPorte.CRegistroISTMO;
		/** Atributo condicional para registrar la región en donde inicia el traslado de los bienes y/o mercancias al interior de los Polos de Desarrollo para el Bienestar del istmo de Tehuantepec.	**/
		UbicacionPoloOrigen?: catCartaPorte.CRegistroISTMO;
		/** Atributo condicional para registrar la vía de ingreso o salida de los bienes y/o mercancías en territorio nacional.	**/
		ViaEntradaSalida?: catCartaPorte.CCveTransporte;
	};
	children: (CartaPorteFiguraTransporte | CartaPorteMercancias | CartaPorteUbicaciones)[];
}

/** Atributo opcional para expresar la clave de producto de la STCC (por sus siglas en inglés, Standard Transportation Commodity Code), cuando el medio de transporte utilizado para el traslado de los bienes y/o mercancías sea ferroviario.
 * @pattern [0-9|]{6,7}
 * @minLength 6
 * @maxLength 7
 **/
export interface ClaveSTCC extends XastElement {
	name: string;
	children: [
		{
			type: 'text';
			/**
			 * @pattern [0-9|]{6,7}
			 * @minLength 6
			 * @maxLength 7
			 **/
			value: string;
		},
	];
}
